from decimal import Decimal, ROUND_HALF_UP


def split_bill(total_cents, n):
    if n < 1:
        raise ValueError("n must be at least 1")
    base = total_cents // n
    remainder = total_cents % n
    return [base + 1] * remainder + [base] * (n - remainder)


def with_tip(total_cents, tip_percent):
    tip_amount = (Decimal(total_cents) * Decimal(tip_percent)) / Decimal(100)
    rounded_tip = int(tip_amount.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    return total_cents + rounded_tip

